SELECT * FROM LOGIC_CARD_POOL_BATCH

    BATCH_NO = #{batchNo}
    AND CARD_TYPE = #{cardType}
    AND ACC_TICKET_TYPE = #{accTicketType}
    AND SOURCE = #{source}
    AND STATUS = #{status}
    AND CREATE_TIME >= #{createTimeBegin}
    AND CREATE_TIME <= #{createTimeEnd}

ORDER BY CREATE_TIME DESC, BATCH_NO DESC

mapper.update:
UPDATE LOGIC_CARD_POOL_TYPE_LOCK
SET LOCK_TIME = SYSTIMESTAMP
WHERE CARD_TYPE = #{cardType} AND LOCK_OWNER = #{lockOwner}

UPDATE LOGIC_CARD_POOL_TYPE_LOCK
SET LOCK_OWNER = NULL, LOCK_TIME = NULL
WHERE CARD_TYPE = #{cardType} AND LOCK_OWNER = #{lockOwner}

UPDATE LOGIC_CARD_POOL_BATCH
FILE_NAME = #{fileName}, FTP_PATH = #{ftpPath}, FILE_SIZE = #{fileSize}, FILE_SHA256 = #{fileSha256}, STATUS = #{status}, ERROR_MSG = #{errorMsg}, FINISH_TIME = #{finishTime}, TOTAL_COUNT = #{totalCount}, VALID_COUNT = #{validCount}, DUPLICATE_COUNT = #{duplicateCount}, INVALID_COUNT = #{invalidCount}, RETRY_COUNT = #{retryCount},
WHERE BATCH_NO = #{batchNo}

UPDATE LOGIC_CARD_POOL_BATCH
SET STATUS = 'FAILED', ERROR_MSG = #{errorMsg}, FINISH_TIME = SYSTIMESTAMP
WHERE BATCH_NO = #{batchNo}
